1	// 入口のサブコマンド pptx の処理。check と同じ検査に合格したときだけ PowerPoint のファイルを書き、
2	// pptx のスキルの scripts/apply_theme.js でテーマの色を書き込み、scripts/office/validate.py で形式を検査する (計画の R10〜R12・U5)。
3	// pptx のスキルは、Claude のデスクトップアプリが配るもの (スキルの一覧での名前は anthropic-skills:pptx)。
4	// ディレクトリは、スキル build が引数で渡す。~/.claude の下などを探さない (計画の KTD11)。
5	// 入口のサブコマンド pptx の引数・出力・終了コードの SSOT は、ファイル src/cli.ts の --help。
6	
7	import { spawnSync } from "node:child_process";
8	import { existsSync, rmSync, statSync, writeFileSync } from "node:fs";
9	import { join, resolve } from "node:path";
10	import { type CheckOptions, type CheckReport, checkDeck, deckPaths, ExecutionError, installedCache } from "../check/deck.ts";
11	import { type CachePaths, venvState } from "../setup/setup.ts";
12	import { applyThemeInput, loadPptxGen, renderPptx } from "./write.ts";
13	
14	/** pptx のスキルのディレクトリと、使う 2 つのスクリプトのパス */
15	export interface PptxSkill {
16	  readonly dir: string;
17	  /** scripts/apply_theme.js */
18	  readonly applyTheme: string;
19	  /** scripts/office/validate.py */
20	  readonly validate: string;
21	}
22	
23	/** pptx のスキルのディレクトリを受け取り、使う 2 つのスクリプトがあることを確認する。無ければ ExecutionError を送出する */
24	export function pptxSkill(dir: string): PptxSkill {
25	  const abs = resolve(dir);
26	  const skill: PptxSkill = {
27	    dir: abs,
28	    applyTheme: join(abs, "scripts", "apply_theme.js"),
29	    validate: join(abs, "scripts", "office", "validate.py"),
30	  };
31	  const missing = [skill.applyTheme, skill.validate].filter((p) => !existsSync(p));
32	  if (missing.length > 0) {
33	    throw new ExecutionError(
34	      `pptx のスキルのディレクトリ ${abs} に、次のファイルが無い:\n${missing.map((p) => `  ${p}`).join("\n")}\n` +
35	        "Claude のデスクトップアプリが配る pptx のスキル (スキルの一覧での名前は anthropic-skills:pptx) のディレクトリを渡す。" +
36	        "マーケットプレイス anthropic-agent-skills のプラグイン document-skills が配る pptx のスキルには、scripts/apply_theme.js が無い",
37	    );
38	  }
39	  return skill;
40	}
41	
42	/**
43	 * テーマの色を PowerPoint のファイルに書き込む処理。pptxPath のファイルを書き換え、利用者に示す出力を返す。
44	 * 失敗したら ExecutionError を送出する。テストで差し替えられるよう、関数として渡す
45	 */
46	export type ApplyTheme = (pptxPath: string, themePath: string) => string;
47	
48	/**
49	 * pptx のスキルの scripts/apply_theme.js を、環境変数 NODE_PATH にキャッシュの node_modules を指定した子プロセスで実行する
50	 * (計画の KTD8)。apply_theme.js は pptxgenjs に同梱の jszip を、require で NODE_PATH から探す
51	 */
52	export function skillApplyTheme(skill: PptxSkill, cache: CachePaths, env: NodeJS.ProcessEnv): ApplyTheme {
53	  return (pptxPath, themePath) => {
54	    const r = spawnSync(process.execPath, [skill.applyTheme, pptxPath, themePath], {
55	      env: { ...env, NODE_PATH: cache.nodeModulesDir },
56	      encoding: "utf8",
57	    });
58	    const output = `${r.stdout}${r.stderr}`.trimEnd();
59	    if (r.error !== undefined || r.status !== 0) {
60	      throw new ExecutionError(
61	        `pptx のスキルの ${skill.applyTheme} が失敗した (終了コード ${String(r.status)}${r.error === undefined ? "" : `、${r.error.message}`}):\n${output}`,
62	      );
63	    }
64	    return output;
65	  };
66	}
67	
68	/** pptx のスキルの scripts/office/validate.py の結果。ok が false なら、形式の誤りがある */
69	export interface ValidateResult {
70	  readonly ok: boolean;
71	  readonly output: string;
72	}
73	
74	/**
75	 * pptx のスキルの scripts/office/validate.py を、キャッシュの venv の Python で実行する。
76	 * 終了コード 0 は誤りなし、1 は形式の誤りあり。それ以外は ExecutionError にする
77	 */
78	export function skillValidate(skill: PptxSkill, cache: CachePaths, pptxPath: string, env: NodeJS.ProcessEnv): ValidateResult {
79	  const r = spawnSync(cache.venvPython, [skill.validate, pptxPath], { env, encoding: "utf8" });
80	  const output = `${r.stdout}${r.stderr}`.trimEnd();
81	  if (r.error === undefined && (r.status === 0 || r.status === 1)) return { ok: r.status === 0, output };
82	  throw new ExecutionError(
83	    `pptx のスキルの ${skill.validate} を、${cache.venvPython} で実行できなかった (終了コード ${String(r.status)}` +
84	      `${r.error === undefined ? "" : `、${r.error.message}`}):\n${output}`,
85	  );
86	}
87	
88	/** サブコマンド pptx の引数 */
89	export interface PptxOptions extends CheckOptions {
90	  /** pptx のスキルのディレクトリ */
91	  readonly skillDir: string;
92	  /** テーマの色を書き込む処理。省略すると、pptx のスキルの scripts/apply_theme.js を実行する */
93	  readonly applyTheme?: ApplyTheme;
94	}
95	
96	/** サブコマンド pptx の結果 */
97	export interface PptxReport {
98	  readonly check: CheckReport;
99	  /** 書いた PowerPoint のファイル。check に指摘があれば null */
100	  readonly pptx: string | null;
101	  /** テーマの色を書き込む処理の出力 */
102	  readonly applyThemeOutput: string;
103	  /** validate.py の結果。check に指摘があれば null */
104	  readonly validate: ValidateResult | null;
105	}
106	
107	/**
108	 * 前に書いた build/deck.pptx を消す。終了コード 2 で終了しうる確認 (pptx のスキル・ライブラリ・資料のディレクトリ) より前に呼ぶ。
109	 * 確認の後に消すと、確認で終了した実行の後に、前の実行のファイルが残る。
110	 * 資料のディレクトリのパスがディレクトリでなければ (無い・通常のファイル)、消すものは無く、後の関数 deckPaths が実行の誤りにする。
111	 * 消せないとき (build/deck.pptx がディレクトリのときなど) は、パスと理由を示す ExecutionError を送出する
112	 */
113	function removePreviousPptx(deckDir: string): void {
114	  const dir = resolve(deckDir);
115	  if (!existsSync(dir) || !statSync(dir).isDirectory()) return;
116	  const pptxPath = join(dir, "build", "deck.pptx");
117	  try {
118	    rmSync(pptxPath, { force: true });
119	  } catch (e) {
120	    throw new ExecutionError(`前に書いた ${pptxPath} を消せない: ${e instanceof Error ? e.message : String(e)}`);
121	  }
122	}
123	
124	/**
125	 * 資料のディレクトリを検査し、指摘が無ければ build/deck.pptx を書き、テーマの色を書き込み、形式を検査する。
126	 * 前に書いた build/deck.pptx は、最初に消す (ファイルがあることと、最後の実行が書いたことを一致させるため)。
127	 * テーマの色の書き込みが失敗したら、書いたファイルも消す。validate.py が形式の誤りを見つけたときは、調べられるようファイルを残す
128	 */
129	export async function buildPptx(deckDir: string, options: PptxOptions): Promise<PptxReport> {
130	  removePreviousPptx(deckDir);
131	  const env = options.env ?? process.env;
132	  const skill = pptxSkill(options.skillDir);
133	  const cache = installedCache(options);
134	  if (venvState(cache) !== "installed") {
135	    throw new ExecutionError(
136	      `ライブラリ (Python の venv) が、キャッシュのディレクトリ ${cache.venvDir} に入っていない。` +
137	        "サブコマンド setup status で状態を確認し、setup install で入れる",
138	    );
139	  }
140	  const paths = deckPaths(deckDir);
141	  const pptxPath = join(paths.buildDir, "deck.pptx");
142	  const themePath = join(paths.buildDir, "theme.json");
143	
144	  const check = await checkDeck(deckDir, options);
145	  if (check.deck === null) return { check, pptx: null, applyThemeOutput: "", validate: null };
146	
147	  writeFileSync(pptxPath, await renderPptx(check.deck, loadPptxGen(cache.nodeModulesDir)));
148	  writeFileSync(themePath, `${JSON.stringify(applyThemeInput(check.deck.theme), null, 2)}\n`);
149	  const applyTheme = options.applyTheme ?? skillApplyTheme(skill, cache, env);
150	  let applyThemeOutput: string;
151	  try {
152	    applyThemeOutput = applyTheme(pptxPath, themePath);
153	  } catch (e) {
154	    rmSync(pptxPath, { force: true });
155	    const message = e instanceof Error ? e.message : String(e);
156	    throw new ExecutionError(`${message}\nテーマの色を書き込めなかったので、PowerPoint のファイル ${pptxPath} は消した`);
157	  }
158	  const validate = skillValidate(skill, cache, pptxPath, env);
159	  return { check, pptx: pptxPath, applyThemeOutput, validate };
160	}
